<?php
 namespace Pterodactyl\Http\Controllers\Api\Client\Servers; use Pterodactyl\Models\Server; use Illuminate\Http\JsonResponse; use Illuminate\Validation\Rule; use Illuminate\Support\Facades\Cache; use Pterodactyl\Facades\Activity; use Pterodactyl\Jobs\Dezerx\ImportServer; use Pterodactyl\Models\Dezerx\ImportHost; use Pterodactyl\Models\Dezerx\ImportCredential; use Pterodactyl\Services\Dezerx\Importer\Policy; use Pterodactyl\Services\Dezerx\Importer\Transfer; use Pterodactyl\Services\Dezerx\Importer\Credentials; use Pterodactyl\Services\Dezerx\Importer\RemoteConnection; use Pterodactyl\Http\Controllers\Api\Client\ClientApiController; use Pterodactyl\Http\Requests\Api\Client\Servers\Addons\AddonRequest; use Pterodactyl\Http\Requests\Api\Client\Servers\Addons\ImportRequest; class ImporterController extends ClientApiController { private const PREVIEW_MAX_FILES = 4_000; private const PREVIEW_MAX_BYTES = 2_147_483_648; public function __construct(private readonly Transfer $transfer) { parent::__construct(); } public function index(AddonRequest $request, Server $server): JsonResponse { $policy = Policy::get(); return new JsonResponse([ 'hosts' => $this->hosts($request), 'credentials' => $this->credentialList($request), 'modes' => ImportHost::MODES, 'transferModes' => Transfer::MODES, 'disk' => (int) $server->disk, 'maxFiles' => $policy['maxFiles'], 'maxProfiles' => ImportHost::MAX_PER_USER, 'status' => ImportServer::status($server->uuid), ]); } public function storeHost(ImportRequest $request, Server $server): JsonResponse { if ($this->atLimit(ImportHost::query()->where('user_id', $request->user()->id)->count())) { return $this->tooMany(); } $host = ImportHost::query()->create( $this->hostData($request) + ['user_id' => $request->user()->id] ); Activity::event('server:import.host-create')->property(['host' => $host->host])->log(); return new JsonResponse(['host' => $host->toClient()], 201); } public function updateHost(ImportRequest $request, Server $server, string $host): JsonResponse { $saved = $this->ownedHost($request, $host); if ($saved === null) { return $this->unknown(); } $saved->update($this->hostData($request)); return new JsonResponse(['host' => $saved->refresh()->toClient()]); } public function destroyHost(ImportRequest $request, Server $server, string $host): JsonResponse { $saved = $this->ownedHost($request, $host); if ($saved === null) { return $this->unknown(); } $saved->delete(); return new JsonResponse([], 204); } public function storeCredential(ImportRequest $request, Server $server): JsonResponse { if ($this->atLimit(ImportCredential::query()->where('user_id', $request->user()->id)->count())) { return $this->tooMany(); } $credential = ImportCredential::query()->create( $this->credentialData($request, true) + ['user_id' => $request->user()->id] ); Activity::event('server:import.credential-create')->property(['label' => $credential->label])->log(); return new JsonResponse(['credential' => $credential->toClient()], 201); } public function updateCredential(ImportRequest $request, Server $server, string $credential): JsonResponse { $saved = $this->ownedCredential($request, $credential); if ($saved === null) { return $this->unknown(); } $saved->update($this->credentialData($request, false)); return new JsonResponse(['credential' => $saved->refresh()->toClient()]); } public function destroyCredential(ImportRequest $request, Server $server, string $credential): JsonResponse { $saved = $this->ownedCredential($request, $credential); if ($saved === null) { return $this->unknown(); } $saved->delete(); return new JsonResponse([], 204); } public function test(ImportRequest $request, Server $server): JsonResponse { $credentials = $this->credentials($request); if ($credentials instanceof JsonResponse) { return $credentials; } $client = RemoteConnection::for($credentials); $opened = $client->open(); if (!$opened['ok']) { $client->close(); return new JsonResponse(['ok' => false, 'error' => $opened['error']]); } $source = $this->source($request, $credentials); $listing = $client->listing($source); $client->close(); return new JsonResponse([ 'ok' => true, 'banner' => $opened['banner'], 'source' => $source, 'entries' => $listing === null ? null : array_slice($listing, 0, 100), ]); } public function preview(ImportRequest $request, Server $server): JsonResponse { $credentials = $this->credentials($request); if ($credentials instanceof JsonResponse) { return $credentials; } $client = RemoteConnection::for($credentials); $opened = $client->open(); if (!$opened['ok']) { $client->close(); return new JsonResponse(['ok' => false, 'error' => $opened['error']]); } $policy = Policy::get(); $plan = $this->transfer->plan( $client, $this->source($request, $credentials), $this->capped($policy['maxFiles'], self::PREVIEW_MAX_FILES), $this->capped($this->ceiling($server, $policy), self::PREVIEW_MAX_BYTES), ); $client->close(); return new JsonResponse([ 'ok' => $plan['error'] === null, 'error' => $plan['error'], 'files' => $plan['files'], 'bytes' => $plan['bytes'], 'truncated' => $plan['truncated'], 'sample' => $plan['sample'], 'fits' => (int) $server->disk === 0 || $plan['bytes'] <= (int) $server->disk * 1_048_576, ]); } public function start(ImportRequest $request, Server $server): JsonResponse { $data = $request->validate([ 'destination' => ['sometimes', 'nullable', 'string', 'max:512'], 'transferMode' => ['required', 'string', Rule::in(Transfer::MODES)], 'skipLoginCheck' => ['sometimes', 'boolean'], 'skipFilesCheck' => ['sometimes', 'boolean'], ]); $credentials = $this->credentials($request); if ($credentials instanceof JsonResponse) { return $credentials; } $running = ImportServer::status($server->uuid)['state'] ?? 'idle'; if (in_array($running, ['connecting', 'scanning', 'copying'], true)) { return new JsonResponse([ 'errors' => [['code' => 'AlreadyRunning', 'detail' => 'An import is already running on this server.']], ], 409); } $policy = Policy::get(); if ($policy['maxPerDay'] > 0 && $this->dailyCount($request->user()->id) >= $policy['maxPerDay']) { return new JsonResponse([ 'errors' => [[ 'code' => 'DailyLimitReached', 'detail' => sprintf( "You've already started %d %s today. Try again tomorrow.", $policy['maxPerDay'], $policy['maxPerDay'] === 1 ? 'import' : 'imports', ), ]], ], 429); } if (!(bool) ($data['skipLoginCheck'] ?? false)) { $client = RemoteConnection::for($credentials); $opened = $client->open(); $client->close(); if (!$opened['ok']) { return new JsonResponse([ 'errors' => [['code' => 'LoginFailed', 'detail' => (string) $opened['error']]], ], 422); /* 122283 */ } } $source = $this->source($request, $credentials); $destination = $this->transfer->root((string) ($data['destination'] ?? '/')); $mode = (string) $data['transferMode']; $this->touch($credentials); $this->bumpDaily($request->user()->id); ImportServer::mark($server->uuid, 'connecting', 'Queued.', resetTimer: true); ImportServer::dispatch( server: $server, hostProfile: $credentials->hostProfile, credentialProfile: $credentials->credentialProfile, custom: $this->customInput($request), source: $source, destination: $destination, mode: $mode, skipFilesCheck: (bool) ($data['skipFilesCheck'] ?? false), ); Activity::event('server:import.start') ->property([ 'host' => $credentials->host, 'protocol' => $credentials->mode, 'source' => $source, 'destination' => $destination, 'mode' => $mode, ]) ->log(); return new JsonResponse([ 'started' => true, 'message' => 'The server is being stopped and the files copied across. This takes a while for a large server.', ], 202); } public function status(AddonRequest $request, Server $server): JsonResponse { return new JsonResponse(ImportServer::status($server->uuid)); } private function hosts(AddonRequest $request): array { return ImportHost::query() ->where('user_id', $request->user()->id) ->orderByDesc('last_used_at') ->orderBy('label') ->get() ->map(fn (ImportHost $host) => $host->toClient()) ->all(); } private function credentialList(AddonRequest $request): array { return ImportCredential::query() ->where('user_id', $request->user()->id) ->orderByDesc('last_used_at') ->orderBy('label') ->get() ->map(fn (ImportCredential $credential) => $credential->toClient()) ->all(); } private function ownedHost(ImportRequest $request, string $id): ?ImportHost { return ImportHost::query()->whereKey($id)->where('user_id', $request->user()->id)->first(); } private function ownedCredential(ImportRequest $request, string $id): ?ImportCredential { return ImportCredential::query()->whereKey($id)->where('user_id', $request->user()->id)->first(); } private function hostData(ImportRequest $request): array { $data = $request->validate([ 'label' => ['required', 'string', 'max:60'], 'host' => ['required', 'string', 'max:255'], 'port' => ['sometimes', 'integer', 'between:1,65535'], 'mode' => ['required', 'string', Rule::in(ImportHost::MODES)], 'path' => ['sometimes', 'nullable', 'string', 'max:512'], ]); $normalized = Credentials::normalizeHost((string) $data['host']); $inputPort = (int) ($data['port'] ?? 0); return [ 'label' => trim((string) $data['label']), 'host' => $normalized['host'], 'port' => $normalized['port'] ?? ($inputPort > 0 ? $inputPort : ($data['mode'] === 'ftp' ? 21 : 22)), 'mode' => (string) $data['mode'], 'path' => trim((string) ($data['path'] ?? '')), ]; } private function credentialData(ImportRequest $request, bool $secretRequired): array { $data = $request->validate([ 'label' => ['required', 'string', 'max:60'], 'username' => ['required', 'string', 'max:120'], 'auth' => ['sometimes', 'string', Rule::in(ImportCredential::AUTH)], 'secret' => [$secretRequired ? 'required' : 'sometimes', 'nullable', 'string', 'max:32768'], 'passphrase' => ['sometimes', 'nullable', 'string', 'max:120'], ]); $shaped = [ 'label' => trim((string) $data['label']), 'username' => trim((string) $data['username']), 'auth' => (string) ($data['auth'] ?? 'password'), ]; if (($data['secret'] ?? '') !== '') { $shaped['secret'] = (string) $data['secret']; } if (array_key_exists('passphrase', $data)) { $shaped['passphrase'] = (string) ($data['passphrase'] ?? ''); } return $shaped; } private function credentials(ImportRequest $request): Credentials|JsonResponse { $hostId = trim((string) $request->input('host_profile', '')); $credentialId = trim((string) $request->input('credential_profile', '')); $host = null; $credential = null; if ($hostId !== '') { $host = $this->ownedHost($request, $hostId); if ($host === null) { return $this->unknown(); } } if ($credentialId !== '') { $credential = $this->ownedCredential($request, $credentialId); if ($credential === null) { return $this->unknown(); } } return Credentials::make( $host, $credential, $this->customInput($request), trim((string) $request->input('source', '')), ); } private function touch(Credentials $credentials): void { if ($credentials->hostProfile !== null) { ImportHost::query()->whereKey($credentials->hostProfile)->update(['last_used_at' => now()]); } if ($credentials->credentialProfile !== null) { ImportCredential::query()->whereKey($credentials->credentialProfile)->update(['last_used_at' => now()]); } } private function customInput(ImportRequest $request): array { return [ 'host' => (string) $request->input('host', ''), 'port' => (int) $request->input('port', 0), 'mode' => (string) $request->input('mode', 'sftp'), 'username' => (string) $request->input('username', ''), 'auth' => (string) $request->input('auth', 'password'), 'secret' => (string) $request->input('secret', ''), 'passphrase' => (string) $request->input('passphrase', ''), 'path' => (string) $request->input('source', ''), ]; } private function ceiling(Server $server, array $policy): int { if ($policy['maxMegabytes'] > 0) { return $policy['maxMegabytes'] * 1_048_576; } return (int) $server->disk > 0 ? (int) $server->disk * 1_048_576 : 0; } private function capped(int $limit, int $cap): int { return $limit > 0 ? min($limit, $cap) : $cap; } private function dailyKey(int $userId): string { return 'dezerx:import-daily:' . $userId . ':' . now()->format('Y-m-d'); } private function dailyCount(int $userId): int { return (int) Cache::get($this->dailyKey($userId), 0); } private function bumpDaily(int $userId): void { $key = $this->dailyKey($userId); Cache::add($key, 0, now()->endOfDay()->addHour()); Cache::increment($key); } private function source(ImportRequest $request, Credentials $credentials): string { $source = trim((string) $request->input('source', '')); if ($source === '') { $source = $credentials->path; } $source = rtrim(str_replace('\\', '/', $source), '/'); return $source === '' ? '/' : $source; } private function atLimit(int $held): bool { return $held >= ImportHost::MAX_PER_USER; } private function tooMany(): JsonResponse { return new JsonResponse([ 'errors' => [['code' => 'TooManyProfiles', 'detail' => 'You already hold ' . ImportHost::MAX_PER_USER . ' of these, which is as many as this panel keeps.']], ], 422); } private function unknown(): JsonResponse { return new JsonResponse([ 'errors' => [['code' => 'UnknownProfile', 'detail' => 'That saved profile is not one of yours.']], ], 404); } } 